-- ===== Step 1C.1 - One list, two facts =======================================

WITH slof_sold AS (
    -- step 1: what we sold in 2024, per brand
    SELECT ds.brand, SUM(f.qty_slof) AS slof_sold_2024
    FROM silver.fact_sales_line f
    JOIN silver.dim_sku ds ON f.sku_key = ds.sku_key
    WHERE f.order_date >= '2024-01-01' AND f.order_date < '2025-01-01'
    GROUP BY ds.brand
),
slof_in_stock AS (
    -- step 2: what we hold today, per brand
    SELECT ds.brand, SUM(s.stock_slof) AS slof_in_stock
    FROM silver.fact_stock_snapshot s
    JOIN silver.dim_sku ds ON s.sku_key = ds.sku_key
    GROUP BY ds.brand
)
-- step 3: put the two side by side
SELECT so.brand, so.slof_sold_2024, st.slof_in_stock
FROM slof_sold so
JOIN slof_in_stock st ON so.brand = st.brand
ORDER BY so.brand;
-- Look at: 20 brands, each with both numbers.


-- ===== Step 1C.2 - What happens with two different lists =====================

-- the warehouse team's own brand list, spelled differently
CREATE OR REPLACE TABLE sandbox.warehouse_brand AS
SELECT DISTINCT replace(lower(brand), ' ', '-') AS brand
FROM silver.dim_sku;

SELECT * FROM sandbox.warehouse_brand ORDER BY brand LIMIT 3;

-- try to match it with the sales brand list
SELECT COUNT(*) AS matched_brands
FROM (SELECT DISTINCT brand FROM silver.dim_sku) s
JOIN sandbox.warehouse_brand w ON s.brand = w.brand;
-- Look at: the warehouse list says brand-a, and matched_brands is 0.


-- ===== Step 0.1 - Pick rows: SELECT and WHERE ================================

