GROUP BY region
ORDER BY outlets DESC;
-- Look at: 5 rows, one per region; JAWA BARAT has the most outlets (10,085).


-- ===== Step 0.3 - Put two tables together: JOIN ==============================

SELECT ds.brand, SUM(f.qty_slof) AS slof_sold_2024
FROM silver.fact_sales_line f
JOIN silver.dim_sku ds ON f.sku_key = ds.sku_key
WHERE f.order_date >= '2024-01-01' AND f.order_date < '2025-01-01'
GROUP BY ds.brand
ORDER BY slof_sold_2024 DESC
LIMIT 5;
-- Look at: the top brand of 2024 is BRAND T.


-- ===== Step 0.4 - Find what is missing: LEFT JOIN and IS NULL ================

SELECT COUNT(*) AS outlets_without_orders_2024
FROM silver.dim_outlet o
LEFT JOIN (
    SELECT DISTINCT outlet_key
    FROM silver.fact_sales_line
    WHERE order_date >= '2024-01-01' AND order_date < '2025-01-01'
) s ON o.outlet_key = s.outlet_key
WHERE s.outlet_key IS NULL;
-- Look at: 15,838 outlets.


-- ===== Step 0.5 - Filter groups: HAVING ======================================

SELECT ds.brand, SUM(f.qty_slof) AS slof_sold_2024
FROM silver.fact_sales_line f
JOIN silver.dim_sku ds ON f.sku_key = ds.sku_key
WHERE f.order_date >= '2024-01-01' AND f.order_date < '2025-01-01'  -- WHERE: filters rows, before grouping
GROUP BY ds.brand
HAVING SUM(f.qty_slof) > 295000                                     -- HAVING: filters groups, after grouping
ORDER BY slof_sold_2024 DESC;
-- Look at: 4 brands: BRAND T, BRAND A, BRAND K and BRAND D.


-- ===== Step 1A.1 - Create a table with the right types, add an index =========

CREATE OR REPLACE TABLE sandbox.sales_target (
    target_id      INTEGER       NOT NULL PRIMARY KEY,   -- whole number, one per row
    distributor_id INTEGER       NOT NULL,               -- whole number, the join key
    month_start    DATE          NOT NULL,               -- a date, no time
    brand          VARCHAR(20)   NOT NULL,               -- text, at most 20 characters
    target_slof    DECIMAL(12,2),                        -- exact number with 2 decimals
    is_active      BOOLEAN       DEFAULT TRUE,           -- yes / no
    created_at     TIMESTAMP     DEFAULT current_timestamp  -- date and time
);

INSERT INTO sandbox.sales_target (target_id, distributor_id, month_start, brand, target_slof)
VALUES (1, 7, DATE '2025-01-01', 'BRAND A', 1500.00),
       (2, 7, DATE '2025-02-01', 'BRAND A', 1650.50),
       (3, 8, DATE '2025-01-01', 'BRAND B',  980.25);

-- index: a lookup list on distributor_id, for queries that look up one distributor
CREATE INDEX idx_sales_target_distributor ON sandbox.sales_target (distributor_id);

SELECT * FROM sandbox.sales_target ORDER BY target_id;
-- Look at: 3 rows; is_active and created_at were filled by their DEFAULT values.

