-- ===== 3.2 - Filter so the engine can skip data (MoM: efficient, not too long) ===

-- A: how many lines shipped in January 2024? (table stored by SKU)
SELECT COUNT(*) AS lines_jan_2024
FROM lab.sales_line_by_sku
WHERE sl_ship_date >= '2024-01-01' AND sl_ship_date < '2024-02-01';

-- B: same question, table stored by date
SELECT COUNT(*) AS lines_jan_2024
FROM lab.sales_line_by_date
WHERE sl_ship_date >= '2024-01-01' AND sl_ship_date < '2024-02-01';

-- C: same question, table stored by date, but the column is wrapped in a function
SELECT COUNT(*) AS lines_jan_2024
FROM lab.sales_line_by_date
WHERE strftime(sl_ship_date, '%Y-%m') = '2024-01';
-- Look at: all three answer 76,909 lines, but rows scanned are A = 6,000,000, B = 122,880, C = 6,000,000.


-- ===== 3.3 - Read only what you need (MoM: efficient, no unneeded cost) ======

-- original
SELECT DISTINCT o.*, ot.ot_channel
FROM source.sales_order o
JOIN source.sales_order_line l ON o.so_order_id = l.sl_order_id
JOIN source.outlet ot          ON o.so_outlet_id = ot.ot_outlet_id
WHERE YEAR(o.so_order_date) = 2024;

-- rewrite
SELECT o.so_order_id, o.so_order_date, o.so_total_amount, o.so_status, ot.ot_channel
FROM source.sales_order o
JOIN source.outlet ot ON o.so_outlet_id = ot.ot_outlet_id
WHERE o.so_order_date >= '2024-01-01' AND o.so_order_date < '2025-01-01';
-- Look at: both return 57,249 rows; rows scanned drop from 1,924,927 to 425,000.


-- ===== 3.4 - Fewer JOINs through the model (MoM: no excessive JOINs) =========

-- bronze: 4 JOINs, net sales formula written by hand
SELECT r.rg_name AS region,
       SUM(l.sl_gross_amount * (1 - l.sl_discount)) AS net_sales
FROM bronze.sales_order_line l
JOIN bronze.sales_order o ON l.sl_order_id = o.so_order_id
JOIN bronze.distributor d ON l.sl_distributor_id = d.dt_distributor_id
JOIN bronze.area a        ON d.dt_area_id = a.ar_area_id
JOIN bronze.region r      ON a.ar_region_id = r.rg_region_id
WHERE o.so_order_date >= '2024-01-01' AND o.so_order_date < '2025-01-01'
GROUP BY r.rg_name
ORDER BY r.rg_name;

-- silver star: 1 JOIN, net_amount already computed
SELECT dd.region, SUM(f.net_amount) AS net_sales
FROM silver.fact_sales_line f
JOIN silver.dim_distributor dd ON f.distributor_key = dd.distributor_key
WHERE f.order_date >= '2024-01-01' AND f.order_date < '2025-01-01'
GROUP BY dd.region
ORDER BY dd.region;
-- Look at: same 5 regions and totals; rows scanned 1,875,957 on bronze vs 369,641 on the silver star.

SELECT region, month_start, net_sales
FROM gold.mart_sales_outlet_region_month
WHERE month_start >= '2024-01-01' AND month_start < '2025-01-01'
ORDER BY region, month_start;
-- Look at: 400 rows scanned.


-- ===== 3.5 - Subquery vs CTE vs temp table (MoM: effective, fewer mistakes, cost) ===

SELECT distributor_key, total_sales
FROM (
    SELECT distributor_key, SUM(net_amount) AS total_sales
    FROM silver.fact_sales_line
    WHERE order_date >= '2024-01-01' AND order_date < '2025-01-01'
    GROUP BY distributor_key
) x
WHERE total_sales > (
    SELECT AVG(total_sales)
    FROM (
        SELECT distributor_key, SUM(net_amount) AS total_sales
        FROM silver.fact_sales_line
        WHERE order_date >= '2024-01-01' AND order_date < '2025-01-01'
        GROUP BY distributor_key
    ) y
)
ORDER BY total_sales DESC;

WITH distributor_sales_2024 AS (
    -- one row per distributor: its 2024 net sales
    SELECT distributor_key, SUM(net_amount) AS total_sales
    FROM silver.fact_sales_line
    WHERE order_date >= '2024-01-01' AND order_date < '2025-01-01'
    GROUP BY distributor_key
)
SELECT distributor_key, total_sales
FROM distributor_sales_2024
WHERE total_sales > (SELECT AVG(total_sales) FROM distributor_sales_2024)
ORDER BY total_sales DESC;

CREATE OR REPLACE TEMP TABLE distributor_sales_2024 AS
SELECT distributor_key, SUM(net_amount) AS total_sales
FROM silver.fact_sales_line
WHERE order_date >= '2024-01-01' AND order_date < '2025-01-01'
GROUP BY distributor_key;

-- check the middle step before you use it
SELECT COUNT(*) AS distributors, SUM(total_sales) AS total_sales_2024
FROM distributor_sales_2024;

SELECT distributor_key, total_sales
FROM distributor_sales_2024
WHERE total_sales > (SELECT AVG(total_sales) FROM distributor_sales_2024)
ORDER BY total_sales DESC;


-- ===== 3.6 - The JOIN on the wrong grain: the 1-minute query (MoM: not too long, no unneeded cost, fewer mistakes) ===

SELECT *
FROM source.distributor_stock_daily
ORDER BY sd_snapshot_date, sd_sku_id, sd_distributor_id
LIMIT 8;

SELECT COUNT(*)                                                      AS row_count,
       COUNT(DISTINCT sd_sku_id)                                     AS skus,
       COUNT(DISTINCT sd_distributor_id)                             AS distributors,
       COUNT(DISTINCT sd_snapshot_date)                              AS days,
       COUNT(DISTINCT (sd_snapshot_date, sd_sku_id, sd_distributor_id)) AS distinct_rows
FROM source.distributor_stock_daily;
-- Look at: 2,920,000 rows = 2,000 SKUs x 4 distributors each x 365 days; distinct_rows equals row_count.
-- Look at: open **Steps, explained**.

WITH slof_sold AS (
    -- one row per brand: slof sold since 2019
    SELECT s.sk_brand, SUM(l.sl_qty_slof) AS slof_sold
    FROM source.sales_order_line l
    JOIN source.sku s ON l.sl_sku_id = s.sk_sku_id
    GROUP BY s.sk_brand
),
stock AS (
    -- one row per brand: all stock over 365 days, divided by 365 days
    SELECT s.sk_brand, SUM(sd.sd_stock_slof) / 365 AS avg_daily_stock
    FROM source.distributor_stock_daily sd
    JOIN source.sku s ON sd.sd_sku_id = s.sk_sku_id
    GROUP BY s.sk_brand
)
SELECT so.sk_brand, so.slof_sold, st.avg_daily_stock
FROM slof_sold so
JOIN stock st ON so.sk_brand = st.sk_brand
ORDER BY so.sk_brand;
-- Look at: 0.03 seconds (about 2,000x faster), and slof_sold now matches a plain SUM(sl_qty_slof) per brand.


