-- ===== 3.8 - Window functions: OVER and LAG ==================================

SELECT region,
       month_start,
       net_sales,
       SUM(net_sales) OVER (PARTITION BY region) AS region_total_2024
FROM gold.mart_sales_outlet_region_month
WHERE month_start >= '2024-01-01' AND month_start < '2025-01-01'
ORDER BY region, month_start;
-- Look at: 60 rows, one per region per month, and every row of a region shows the same region_total_2024.

SELECT region,
       month_start,
       net_sales,
       LAG(net_sales) OVER (PARTITION BY region ORDER BY month_start) AS last_month_sales,
       net_sales - LAG(net_sales) OVER (PARTITION BY region ORDER BY month_start) AS change_vs_last_month
FROM gold.mart_sales_outlet_region_month
WHERE month_start >= '2024-01-01' AND month_start < '2025-01-01'
ORDER BY region, month_start;
-- Look at: January 2024 has last_month_sales = NULL; every later month shows the month before it.


-- ===== Step 1B.1 - Look at dim A =============================================

SELECT distributor_key, distributor_id, distributor_name, area, region,
       valid_from, valid_to, is_current
FROM silver.dim_distributor
WHERE distributor_id IN (7, 8, 9)
ORDER BY distributor_id;
-- Look at: 3 rows, each with is_current = true and valid_to = NULL.


-- ===== Step 1B.2 - Create temp dim A =========================================

CREATE OR REPLACE TABLE sandbox.dim_distributor_tmp AS
SELECT *
FROM silver.dim_distributor
WHERE distributor_id IN (7, 8, 9);

-- new versions get keys from 2001, so they are easy to spot
CREATE OR REPLACE SEQUENCE sandbox.dim_distributor_tmp_seq START WITH 2001;

SELECT * FROM sandbox.dim_distributor_tmp ORDER BY distributor_id;
-- Look at: the same 3 rows, now in sandbox.


-- ===== Step 1B.3 - Tonight's source file arrives =============================

CREATE OR REPLACE TABLE sandbox.distributor_changes AS
SELECT * FROM (VALUES
    (7,    'Distributor#0007', 'SEMARANG', 'JAWA TENGAH'),  -- moved
    (8,    'Distributor#0008', 'BEKASI',   'JAWA BARAT'),   -- same
    (9,    'Distributor#0009', 'BANDUNG',  'JAWA BARAT'),   -- same
    (1001, 'Distributor#1001', 'JAKARTA',  'JAWA BARAT')    -- new
) AS t(distributor_id, distributor_name, area, region);

SELECT * FROM sandbox.distributor_changes ORDER BY distributor_id;
-- Look at: 4 rows: one moved, two unchanged, one new.


-- ===== Step 1B.4 - The SP, part A: find what changed =========================

SELECT
    c.distributor_id,
    d.area   AS area_in_dim,
    c.area   AS area_in_source,
    CASE
        WHEN d.distributor_id IS NULL                  THEN 'new'
        WHEN d.area <> c.area OR d.region <> c.region  THEN 'changed'
        ELSE 'same'
    END AS change_type
FROM sandbox.distributor_changes c
LEFT JOIN sandbox.dim_distributor_tmp d
       ON c.distributor_id = d.distributor_id
      AND d.is_current
ORDER BY c.distributor_id;
-- Look at: 7 = changed, 8 and 9 = same, 1001 = new.


-- ===== Step 1B.5 - The SP, part B: close the old row =========================

UPDATE sandbox.dim_distributor_tmp AS d
SET valid_to   = DATE '2025-08-03',  -- tonight's load date
    is_current = FALSE
FROM sandbox.distributor_changes c
WHERE d.distributor_id = c.distributor_id
  AND d.is_current
  AND (d.area <> c.area OR d.region <> c.region);

SELECT * FROM sandbox.dim_distributor_tmp ORDER BY distributor_id, valid_from;
-- Look at: distributor 7 now has valid_to = 2025-08-03 and is_current = false. Nothing was deleted.


-- ===== Step 1B.6 - The SP, part C: insert the new rows =======================

INSERT INTO sandbox.dim_distributor_tmp
SELECT
    nextval('sandbox.dim_distributor_tmp_seq') AS distributor_key,
    c.distributor_id,
    c.distributor_name,
    c.area,
    c.region,
    DATE '2025-08-03'  AS valid_from,
    CAST(NULL AS DATE) AS valid_to,
    TRUE               AS is_current
FROM sandbox.distributor_changes c
LEFT JOIN sandbox.dim_distributor_tmp d
       ON c.distributor_id = d.distributor_id
      AND d.is_current
-- no current row: either it was closed in 1B.5, or it is new
WHERE d.distributor_id IS NULL;

SELECT * FROM sandbox.dim_distributor_tmp ORDER BY distributor_id, valid_from;
-- Look at: 5 rows. Distributor 7 has two versions (key 7 closed, key 2001 current); 1001 is new with key 2002; 8 and 9 are untouched.


-- ===== Step 1B.7 - Ask history questions =====================================

-- where was distributor 7 on a given date?
SELECT distributor_key, area, region
FROM sandbox.dim_distributor_tmp
WHERE distributor_id = 7
  AND DATE '2024-06-01' >= valid_from
  AND DATE '2024-06-01' <  COALESCE(valid_to, DATE '9999-12-31');

-- and today?
SELECT distributor_key, area, region
FROM sandbox.dim_distributor_tmp
WHERE distributor_id = 7 AND is_current;
-- Look at: June 2024 = BOGOR (key 7); today = SEMARANG (key 2001).


-- ===== Step 1B.8 - The real job: no hard-coded values ========================

-- part B: close the current row of every distributor whose tracked columns changed
UPDATE sandbox.dim_distributor_tmp AS d
SET valid_to   = current_date,
    is_current = FALSE
FROM sandbox.distributor_changes c
WHERE d.distributor_id = c.distributor_id
  AND d.is_current
  AND (   d.distributor_name IS DISTINCT FROM c.distributor_name
       OR d.area             IS DISTINCT FROM c.area
       OR d.region           IS DISTINCT FROM c.region);

-- part C: add a current row for every distributor that has none (changed or new)
INSERT INTO sandbox.dim_distributor_tmp
SELECT nextval('sandbox.dim_distributor_tmp_seq'),
       c.distributor_id, c.distributor_name, c.area, c.region,
       current_date, CAST(NULL AS DATE), TRUE
FROM sandbox.distributor_changes c
LEFT JOIN sandbox.dim_distributor_tmp d
       ON c.distributor_id = d.distributor_id
      AND d.is_current
WHERE d.distributor_id IS NULL;

SELECT COUNT(*) AS rows_in_dim FROM sandbox.dim_distributor_tmp;
-- Look at: rows_in_dim is still 5: no row was closed and no row was added.

-- the source system sends a new file (we play the source system here)
UPDATE sandbox.distributor_changes SET area = 'CIREBON' WHERE distributor_id = 8;

SELECT * FROM sandbox.dim_distributor_tmp
WHERE distributor_id = 8
ORDER BY valid_from;
-- Look at: distributor 8 has two rows now: BEKASI closed today, CIREBON current from today.
